(function(){
  var IMG_START = 'data:image/jpeg;base64,';
  var IMG_GOAL  = 'data:image/jpeg;base64,';
  var IMG_SAVED = 'data:image/jpeg;base64,';

  var ROUNDS = 5;

  var STYLE_ID = 'pk-soccerfields-style';
  function ensureStyle(){
    if(document.getElementById(STYLE_ID)) return;
    var s = document.createElement('style');
    s.id = STYLE_ID;
    s.textContent =
      '.pk-scene{position:relative;width:100%;max-width:260px;margin:0 auto 14px;aspect-ratio:306/603;border-radius:14px;overflow:hidden;background:#85B7EB;}' +
      '.pk-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .45s ease;}' +
      '.pk-img.pk-show{opacity:1;}' +
      '.pk-banner{position:absolute;top:38%;left:0;right:0;text-align:center;font-size:32px;font-weight:800;letter-spacing:1px;opacity:0;transform:translateY(-50%) scale(.4);transition:all .3s cubic-bezier(.2,1.6,.4,1);text-shadow:0 2px 0 rgba(0,0,0,.25);pointer-events:none;}' +
      '.pk-banner.pk-pop{opacity:1;transform:translateY(-50%) scale(1);}' +
      '.pk-banner.pk-goal{color:#62CBC9;}' +
      '.pk-banner.pk-saved{color:#CF3339;}' +
      '.pk-dots{display:flex;justify-content:center;gap:8px;margin-bottom:12px;}' +
      '.pk-dot{width:16px;height:16px;border-radius:50%;background:#e8e4d8;border:2px solid #cfc9b8;}' +
      '.pk-dot.pk-goal{background:#62CBC9;border-color:#3a9d95;}' +
      '.pk-dot.pk-saved{background:#CF3339;border-color:#9c2731;}' +
      '.pk-confetti{position:absolute;top:-10px;width:7px;height:12px;opacity:0;}' +
      '.pk-confetti.pk-fall{animation:pkfall 1.1s ease-in forwards;}' +
      '@keyframes pkfall{0%{opacity:1;transform:translateY(0) rotate(0deg);}100%{opacity:0;transform:translateY(260px) rotate(520deg);}}' +
      '.pk-levelcard{width:100%;text-align:left;padding:12px 16px;margin-bottom:10px;border-radius:12px;border:2px solid #e0dccb;background:#fff;cursor:pointer;}' +
      '.pk-levelcard b{display:block;font-size:15px;color:#081F2C;}' +
      '.pk-levelcard span{display:block;font-size:12px;color:#666;margin-top:2px;}' +
      '.pk-levelcard.pk-current{border-color:#62CBC9;background:#eefaf9;}';
    document.head.appendChild(s);
  }

  var LEVELS = [
    {id:1, label:'Level 1', name:'Add & subtract', desc:'Within 20'},
    {id:2, label:'Level 2', name:'Times tables', desc:'Multiplication facts'},
    {id:3, label:'Level 3', name:'Division', desc:'Whole-number answers'}
  ];

  function genDivision(){
    var divisor = 2 + Math.floor(Math.random()*9);
    var quotient = 2 + Math.floor(Math.random()*9);
    var dividend = divisor*quotient;
    return {q: dividend+' \u00F7 '+divisor, a: quotient};
  }

  function genQuestion(level, ctx){
    if(level===1) return ctx.math.gen('mixed', 0);
    if(level===2) return ctx.math.gen('mul', 2);
    return genDivision();
  }

  function buildOptions(correct){
    var opts = [correct];
    var guard = 0;
    while(opts.length<3 && guard<50){
      guard++;
      var delta = Math.floor(Math.random()*9)-4;
      if(delta===0) delta = 1;
      var val = correct+delta;
      if(val>0 && opts.indexOf(val)===-1) opts.push(val);
    }
    for(var i=opts.length-1;i>0;i--){
      var j = Math.floor(Math.random()*(i+1));
      var t = opts[i]; opts[i]=opts[j]; opts[j]=t;
    }
    return opts;
  }

  function start(host, ctx){
    ensureStyle();

    var level = ctx.state.soccerLevel || null;
    var round = 0, results = [], locked = false, currentAnswer = null;

    render();

    function render(){
      if(level===null){ renderLevelPicker(); }
      else { round = 0; results = []; renderShootout(); }
    }

    function renderLevelPicker(){
      var cards = LEVELS.map(function(lv){
        return '<div class="pk-levelcard" data-lvl="'+lv.id+'">' +
          '<b>'+lv.label+': '+lv.name+'</b><span>'+lv.desc+'</span></div>';
      }).join('');
      host.innerHTML =
        '<div class="center">' +
          '<p class="h3">Clover is warming up for a penalty shootout.</p>' +
          '<p class="sub">Pick a level to help Clover practice.</p>' +
          cards +
        '</div>';
      Array.prototype.forEach.call(host.querySelectorAll('[data-lvl]'), function(card){
        card.addEventListener('pointerup', function(){
          level = parseInt(card.dataset.lvl, 10);
          ctx.state.soccerLevel = level;
          render();
        });
      });
    }

    function renderShootout(){
      var lv = LEVELS[level-1];
      host.innerHTML =
        '<div class="center">' +
          '<p class="sub">'+lv.label+': '+lv.name+'</p>' +
          '<div class="pk-dots" id="pk-dots"></div>' +
          '<div class="pk-scene" id="pk-scene">' +
            '<img class="pk-img pk-show" id="pk-img-start" src="'+IMG_START+'">' +
            '<img class="pk-img" id="pk-img-goal" src="'+IMG_GOAL+'">' +
            '<img class="pk-img" id="pk-img-saved" src="'+IMG_SAVED+'">' +
            '<div class="pk-banner" id="pk-banner"></div>' +
          '</div>' +
          '<p class="bigproblem" id="pk-qtext"></p>' +
          '<div class="row" id="pk-opts"></div>' +
          '<p class="fb" id="pk-fb">&nbsp;</p>' +
        '</div>' +
        '<div class="row center mt">' +
          '<button class="btn ghost sm" id="pk-changelevel">Change level</button>' +
          '<button class="btn ghost sm" id="pk-close">\u2190 Map</button>' +
        '</div>';

      host.querySelector('#pk-changelevel').addEventListener('pointerup', function(){
        level = null; render();
      });
      host.querySelector('#pk-close').addEventListener('pointerup', function(){
        ctx.close();
      });

      renderDots();
      nextRound();
    }

    function renderDots(){
      var dotsEl = host.querySelector('#pk-dots');
      if(!dotsEl) return;
      dotsEl.innerHTML = '';
      for(var i=0;i<ROUNDS;i++){
        var d = document.createElement('div');
        d.className = 'pk-dot' + (results[i]==='goal' ? ' pk-goal' : results[i]==='saved' ? ' pk-saved' : '');
        dotsEl.appendChild(d);
      }
    }

    function showImg(which){
      ['pk-img-start','pk-img-goal','pk-img-saved'].forEach(function(id){
        var im = host.querySelector('#'+id);
        if(im) im.classList.toggle('pk-show', id===which);
      });
    }

    function spawnConfetti(){
      var scene = host.querySelector('#pk-scene');
      if(!scene) return;
      var colors = ['#62CBC9','#FAC775','#7F77DD','#97C459','#F09595'];
      for(var i=0;i<20;i++){
        var c = document.createElement('div');
        c.className = 'pk-confetti pk-fall';
        c.style.left = (Math.random()*100)+'%';
        c.style.background = colors[i % colors.length];
        c.style.animationDelay = (Math.random()*0.2)+'s';
        scene.appendChild(c);
        (function(el){ setTimeout(function(){ el.remove(); }, 1400); })(c);
      }
    }

    function nextRound(){
      if(round >= ROUNDS){ renderResults(); return; }
      locked = false;
      var bannerEl = host.querySelector('#pk-banner');
      if(bannerEl){ bannerEl.className = 'pk-banner'; bannerEl.textContent=''; }
      showImg('pk-img-start');
      var fbEl = host.querySelector('#pk-fb');
      if(fbEl){ fbEl.textContent = '\u00A0'; fbEl.className = 'fb'; }

      var q = genQuestion(level, ctx);
      currentAnswer = q.a;
      host.querySelector('#pk-qtext').textContent = q.q + ' = ?';
      var optsEl = host.querySelector('#pk-opts');
      optsEl.innerHTML = '';
      buildOptions(q.a).forEach(function(o){
        var b = document.createElement('button');
        b.className = 'q-opt';
        b.textContent = o;
        b.addEventListener('pointerup', function(){ answer(o); });
        optsEl.appendChild(b);
      });
    }

    function answer(picked){
      if(locked) return;
      locked = true;
      var correct = picked === currentAnswer;
      Array.prototype.forEach.call(host.querySelectorAll('#pk-opts .q-opt'), function(b){
        b.disabled = true;
        if(parseInt(b.textContent,10) === currentAnswer) b.style.borderColor = '#62CBC9';
      });

      var bannerEl = host.querySelector('#pk-banner');
      var fbEl = host.querySelector('#pk-fb');

      if(correct){
        showImg('pk-img-goal');
        bannerEl.classList.add('pk-goal');
        bannerEl.textContent = 'GOAL!';
        requestAnimationFrame(function(){ bannerEl.classList.add('pk-pop'); });
        spawnConfetti();
        fbEl.textContent = 'Nice shot!';
        fbEl.className = 'fb ok';
        results[round] = 'goal';
      } else {
        showImg('pk-img-saved');
        bannerEl.classList.add('pk-saved');
        bannerEl.textContent = 'SAVED';
        requestAnimationFrame(function(){ bannerEl.classList.add('pk-pop'); });
        fbEl.textContent = 'Blocked \u2014 the answer was ' + currentAnswer + '.';
        fbEl.className = 'fb no';
        results[round] = 'saved';
      }
      renderDots();
      round++;
      setTimeout(nextRound, 1500);
    }

    function renderResults(){
      var scored = results.filter(function(r){ return r==='goal'; }).length;
      var earnedStar = scored >= 4;
      var coins = scored * 2;
      ctx.award({coins: coins, star: earnedStar});

      var lv = LEVELS[level-1];
      var cloverImg = earnedStar ? ctx.clover.cele : ctx.clover.head;
      var msg = earnedStar
        ? 'Clover scored ' + scored + ' of ' + ROUNDS + '! Great shootout.'
        : 'Clover scored ' + scored + ' of ' + ROUNDS + '. Want to try again?';

      host.innerHTML =
        '<div class="center">' +
          '<img src="'+cloverImg+'" style="width:96px;height:96px;object-fit:contain;margin-bottom:10px;">' +
          '<p class="h3">'+msg+'</p>' +
          '<p class="sub">'+lv.label+': '+lv.name+'</p>' +
        '</div>' +
        '<div class="row center mt">' +
          '<button class="btn green" id="pk-again">Shoot again</button>' +
          '<button class="btn teal" id="pk-changelevel2">Change level</button>' +
          '<button class="btn ghost" id="pk-close2">\u2190 Map</button>' +
        '</div>';

      host.querySelector('#pk-again').addEventListener('pointerup', function(){
        round = 0; results = []; renderShootout();
      });
      host.querySelector('#pk-changelevel2').addEventListener('pointerup', function(){
        level = null; render();
      });
      host.querySelector('#pk-close2').addEventListener('pointerup', function(){
        ctx.close();
      });
    }
  }

  window.Stops.register('7F', { name:'Soccer Fields', start:start });
})();
